#!/usr/bin/env node
// Generates the feature registry, seed list and job list from features/*, and links every feature
// into the apps that use it. Run `pnpm gen` after adding a feature. Never edit the generated files by hand.
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { execSync } from "node:child_process";

const root = new URL("..", import.meta.url).pathname;
const features = readdirSync(join(root, "features"))
  .filter((d) => existsSync(join(root, "features", d, "feature.ts")) && existsSync(join(root, "features", d, "package.json")))
  .sort()
  .map((dir) => ({ dir, pkg: JSON.parse(readFileSync(join(root, "features", dir, "package.json"), "utf8")).name, has: (f) => existsSync(join(root, "features", dir, f)) }));

const ident = (d) => d.replace(/[^a-zA-Z0-9]/g, "_");
const banner = "// Generated by scripts/gen-features.mjs. Do not edit.\n";
const write = (file, body) => {
  mkdirSync(join(file, ".."), { recursive: true });
  const prev = existsSync(file) ? readFileSync(file, "utf8") : "";
  if (prev !== body) writeFileSync(file, body);
};

// School app: features + seeds
write(join(root, "apps/school/src/generated/features.ts"), banner +
  `import { orderFeatures } from "@smw/feature-kit";\n` +
  features.map((f) => `import ${ident(f.dir)} from "${f.pkg}/feature";`).join("\n") +
  `\n\n/** Every feature, in dependency order. */\nexport const FEATURES = orderFeatures([${features.map((f) => ident(f.dir)).join(", ")}]);\n`);

const seeds = features.filter((f) => f.has("seed.ts"));
write(join(root, "apps/school/src/generated/seeds.ts"), banner +
  `import type { FeatureSeed } from "@smw/feature-kit";\n` +
  seeds.map((f) => `import ${ident(f.dir)} from "${f.pkg}/seed";`).join("\n") +
  `\n\nexport const SEEDS: Record<string, FeatureSeed> = { ${seeds.map((f) => `${JSON.stringify(f.dir)}: ${ident(f.dir)}`).join(", ")} };\n`);

// Worker: jobs.ts default-exports Record<jobName, (data) => Promise<void>>
const jobs = features.filter((f) => f.has("jobs.ts"));
write(join(root, "apps/worker/src/generated/jobs.ts"), banner +
  jobs.map((f) => `import ${ident(f.dir)} from "${f.pkg}/jobs";`).join("\n") +
  `\n\nexport const FEATURE_JOBS = [${jobs.map((f) => ident(f.dir)).join(", ")}];\n`);

// Link features into the apps
let changed = false;
for (const [app, filter] of [["school", () => true], ["worker", (f) => f.has("jobs.ts")], ["console", () => true]]) {
  const file = join(root, "apps", app, "package.json");
  const pkg = JSON.parse(readFileSync(file, "utf8"));
  pkg.dependencies ??= {};
  for (const f of features.filter(filter)) {
    if (!pkg.dependencies[f.pkg]) { pkg.dependencies[f.pkg] = "workspace:*"; changed = true; }
  }
  writeFileSync(file, JSON.stringify(pkg, null, 2) + "\n");
}
if (changed) execSync("pnpm install --offline --silent", { cwd: root, stdio: "inherit" });
console.log(`features: ${features.map((f) => f.dir).join(", ") || "none"}`);
